/**
 * Compile-time drift check between the hand-written client types (types.ts) and the
 * backend's OpenAPI schema (schema.d.ts, generated by `pnpm gen:api`).
 * If the backend contract changes, `pnpm typecheck` fails here. No runtime code.
 */
import type { components } from './schema'
import type * as T from './types'

type S = components['schemas']

/** Resolves to `true` only if A and B are mutually assignable. */
type Same<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false
/** Request bodies: what the client sends must be accepted by the server schema. */
type Accepts<Server, Client> = [Client] extends [Server] ? true : false

function check<_ extends true>(): void {}

// Responses: the server shape must satisfy what the client reads.
check<Same<T.Company, S['Company']>>()
check<Accepts<T.Agent, S['Agent']>>()
check<Accepts<T.Department, S['Department']>>()
check<Accepts<T.AuditEvent, S['AuditEvent']>>()
check<Accepts<T.Health, S['Health']>>()
check<Accepts<T.Me, S['Me']>>()
check<Accepts<T.RuntimeInfo, S['RuntimeInfo']>>()

// Requests: the server must accept everything the client sends.
check<Accepts<S['CompanyCreate'], T.CreateCompanyRequest>>()
check<Accepts<S['CompanyUpdate'], T.UpdateCompanyRequest>>()
check<Accepts<S['AgentCreate'], T.CreateAgentRequest>>()
check<Accepts<S['AgentUpdate'], T.UpdateAgentRequest>>()
check<Accepts<S['DepartmentCreate'], T.CreateDepartmentRequest>>()
check<Accepts<S['DepartmentUpdate'], T.UpdateDepartmentRequest>>()
